52.   await Dexie.delete('/sqleet');
53.   const encryptionKey = await saveRandomEncryptionKey();
54.   const engine = new SQLeetEngine('/worker/sqleet-worker.js', SQLeetSchemata.getLatest(), encryptionKey);
