20. import ko from 'knockout';
21. import {LegalHoldStatus} from '@wireapp/protocol-messaging';
22. import {StatusCodes as HTTP_STATUS} from 'http-status-codes';
23. import {AssetOptions, AssetRetentionPolicy} from '@wireapp/api-client/src/asset/';
24. import {singleton, container} from 'tsyringe';
25. 
26. import {Logger, getLogger} from 'Util/Logger';
27. import {loadFileBuffer, loadImage, downloadBlob} from 'Util/util';
28. import {WebWorker} from 'Util/worker';
29. 
30. import {AssetService} from './AssetService';
31. import {Conversation} from '../entity/Conversation';
32. import {decryptAesAsset} from './AssetCrypto';
33. import {AssetRemoteData} from './AssetRemoteData';
34. import {getAssetUrl, setAssetUrl} from './AssetURLCache';
35. import type {User} from '../entity/User';
36. import {FileAsset} from '../entity/message/FileAsset';
37. import {AssetTransferState} from './AssetTransferState';
38. import {Core} from '../service/CoreSingleton';
39. 
40. export interface CompressedImage {
41.   compressedBytes: Uint8Array;
42.   compressedImage: HTMLImageElement;
43. }
44. 
45. export interface AssetUploadOptions extends AssetOptions {
46.   domain?: string;
47.   expectsReadConfirmation: boolean;
48.   legalHoldStatus?: LegalHoldStatus;
49. }
50. 
51. export interface UploadStatus {
52.   messageId: string;
53.   progress: ko.Observable<number>;
54. }
55. 
56. @singleton()
57. export class AssetRepository {
58.   readonly uploadProgressQueue: ko.ObservableArray<UploadStatus> = ko.observableArray();
59.   readonly uploadCancelTokens: {[messageId: string]: () => void} = {};
60.   logger: Logger;
61. 
62.   constructor(
63.     private readonly assetService = container.resolve(AssetService),
64.     private readonly core = container.resolve(Core),
65.   ) {
66.     this.logger = getLogger('AssetRepository');
67.   }
68. 
69.   get assetCoreService() {
70.     return this.core.service!.asset;
71.   }
72. 
73.   async getObjectUrl(asset: AssetRemoteData): Promise<string | undefined> {
74.     const objectUrl = getAssetUrl(asset.identifier);
75.     if (objectUrl) {
76.       return objectUrl;
77.     }
78. 
79.     const blob = await this.load(asset);
80.     if (!blob) {
81.       return undefined;
82.     }
83.     const url = window.URL.createObjectURL(blob);
84.     return setAssetUrl(asset.identifier, url);
85.   }
86. 
87.   public async load(asset: AssetRemoteData): Promise<undefined | Blob> {
88.     try {
89.       let plaintext: ArrayBuffer;
90.       const {buffer, mimeType} = await this.loadBuffer(asset);
91.       const isEncryptedAsset = !!asset.otrKey && !!asset.sha256;
92. 
93.       if (isEncryptedAsset) {
94.         const otrKey = asset.otrKey instanceof Uint8Array ? asset.otrKey : Uint8Array.from(Object.values(asset.otrKey));
95.         const sha256 = asset.sha256 instanceof Uint8Array ? asset.sha256 : Uint8Array.from(Object.values(asset.sha256));
96.         plaintext = await decryptAesAsset(buffer, otrKey.buffer, sha256.buffer);
97.       } else {
98.         plaintext = buffer;
99.       }
100.       return new Blob([new Uint8Array(plaintext)], {type: mimeType});
101.     } catch (error) {
102.       const errorMessage = error?.message || '';
103.       const isAssetNotFound = errorMessage.endsWith(HTTP_STATUS.NOT_FOUND);
104.       const isServerError = errorMessage.endsWith(HTTP_STATUS.INTERNAL_SERVER_ERROR);
105. 
106.       const isExpectedError = isAssetNotFound || isServerError;
107.       if (!isExpectedError) {
108.         throw error;
109.       }
110.       return undefined;
111.     }
112.   }
113. 
114.   public generateAssetUrl(asset: AssetRemoteData) {
115.     switch (asset.urlData.version) {
116.       case 3:
117.         return this.assetService.generateAssetUrlV3(
118.           asset.urlData.assetKey,
119.           asset.urlData.assetToken,
120.           asset.urlData.forceCaching,
121.         );
122.       case 2:
123.         return this.assetService.generateAssetUrlV2(
124.           asset.urlData.assetId,
125.           asset.urlData.conversationId,
126.           asset.urlData.forceCaching,
127.         );
128.       case 1:
129.         return this.assetService.generateAssetUrl(
130.           asset.urlData.assetId,
131.           asset.urlData.conversationId,
132.           asset.urlData.forceCaching,
133.         );
134.       default:
135.         throw Error('Cannot map URL data.');
136.     }
137.   }
138. 
139.   private loadBuffer(asset: AssetRemoteData) {
140.     const request = this.core.service!.asset.downloadAsset(asset.urlData, fraction => {
141.       asset.downloadProgress(fraction * 100);
142.     });
143.     asset.cancelDownload = request.cancel;
144.     return request.response;
