20. import {CRUDEngine, error as StoreEngineError} from '@wireapp/store-engine';
21. import {IndexedDBEngine} from '@wireapp/store-engine-dexie';
22. import {SQLeetEngine} from '@wireapp/store-engine-sqleet';
23. import Dexie, {Transaction} from 'dexie';
24. import {singleton} from 'tsyringe';
25. 
26. import {Logger, getLogger} from 'Util/Logger';
27. import {loadValue, storeValue} from 'Util/StorageUtil';
28. 
29. import {StorageSchemata} from './StorageSchemata';
30. import {StorageError} from '../error/StorageError';
31. import {DexieDatabase} from './DexieDatabase';
32. 
33. interface DatabaseListener {
34.   callback: DatabaseListenerCallback;
35.   store: string;
36.   type: DEXIE_CRUD_EVENT;
37. }
38. 
39. export type DatabaseListenerCallback = (changes: {obj: any; oldObj: any}) => void;
40. 
41. enum DEXIE_CRUD_EVENT {
42.   DELETING = 'deleting',
43.   UPDATING = 'updating',
44. }
45. 
46. @singleton()
47. export class StorageService {
48.   public db?: DexieDatabase;
49.   private readonly dbListeners: DatabaseListener[] = [];
50.   private hasHookSupport: boolean;
51.   private engine: CRUDEngine;
52.   public isTemporaryAndNonPersistent: boolean;
53.   private readonly logger: Logger;
54.   public dbName?: string;
55. 
56.   constructor() {
57.     this.logger = getLogger('StorageService');
58.   }
59. 
60.   //##############################################################################
61.   // Initialization
62.   //##############################################################################
63. 
64.   /**
65.    * Initialize the IndexedDB for a user.
66.    *
67.    * @param userId User ID
68.    * @param requestPersistentStorage if a persistent storage should be requested
69.    * @returns Resolves with the database name
70.    */
71.   init(engine: CRUDEngine): string {
72.     this.engine = engine;
73.     this.dbName = this.engine.storeName;
74.     this.hasHookSupport = this.engine instanceof IndexedDBEngine;
75.     this.isTemporaryAndNonPersistent = this.engine instanceof SQLeetEngine;
76. 
77.     try {
78.       if (this.hasHookSupport) {
79.         this.db = this.engine['db'];
80.         this._initCrudHooks(this.db);
81.       }
82.       return this.dbName;
83.     } catch (error) {
84.       const logMessage = `Failed to initialize database '${this.dbName}': ${error.message || error}`;
85.       this.logger.error(logMessage, {error});
86.       throw new StorageError(StorageError.TYPE.FAILED_TO_OPEN, StorageError.MESSAGE.FAILED_TO_OPEN);
87.     }
88.   }
89. 
90.   private _initCrudHooks(db: DexieDatabase): void {
91.     const callListener = (
92.       table: string,
93.       eventType: string,
94.       obj: Object,
95.       updatedObj: Object,
96.       transaction: Transaction,
97.     ) => {
98.       transaction.on('complete', () => {
99.         this.dbListeners
100.           .filter(listener => listener.store === table && listener.type === eventType)
101.           .forEach(({callback}) => callback({obj: updatedObj, oldObj: obj}));
102.       });
103.     };
104. 
105.     const listenableTables = [StorageSchemata.OBJECT_STORE.EVENTS];
106. 
107.     listenableTables.forEach(table => {
108.       db.table(table).hook(
109.         DEXIE_CRUD_EVENT.UPDATING,
110.         function (modifications: Object, primaryKey: string, obj: Object, transaction: Transaction): void {
111.           this.onsuccess = updatedObj => callListener(table, DEXIE_CRUD_EVENT.UPDATING, obj, updatedObj, transaction);
112.         },
113.       );
114. 
115.       db.table(table).hook(
116.         DEXIE_CRUD_EVENT.DELETING,
117.         function (primaryKey: string, obj: Object, transaction: Transaction): void {
118.           this.onsuccess = (): void => callListener(table, DEXIE_CRUD_EVENT.DELETING, obj, undefined, transaction);
119.         },
120.       );
121.     });
122.   }
123. 
124.   addUpdatedListener(storeName: string, callback: DatabaseListenerCallback): void {
125.     this.dbListeners.push({callback, store: storeName, type: DEXIE_CRUD_EVENT.UPDATING});
126.   }
127. 
128.   addDeletedListener(storeName: string, callback: DatabaseListenerCallback): void {
129.     this.dbListeners.push({callback, store: storeName, type: DEXIE_CRUD_EVENT.DELETING});
130.   }
131. 
132.   //##############################################################################
133.   // Interactions
134.   //##############################################################################
135. 
136.   /**
137.    * Clear all stores.
138.    *
139.    * @returns Resolves when all stores have been cleared
140.    */
141.   async clearStores(): Promise<void[]> {
142.     const deleteStorePromises = this.isTemporaryAndNonPersistent
143.       ? [this.engine.purge()]
144.       : Object.keys(this.db?._dbSchema ?? [])
145.           // avoid clearing tables needed by third parties (dexie-observable for eg)
146.           .filter(table => !table.startsWith('_'))
147.           .map(storeName => this.deleteStore(storeName));
148.     return Promise.all(deleteStorePromises);
149.   }
150. 
151.   /**
152.    * Removes persisted data.
153.    *
154.    * @param storeName Name of the object store
155.    * @param primaryKey Primary key
156.    * @returns Resolves when the object is deleted
157.    */
158.   async delete(storeName: string, primaryKey: string): Promise<string> {
159.     if (this.hasHookSupport) {
160.       return this.engine.delete(storeName, primaryKey);
161.     }
162. 
163.     const oldRecord = await this.engine.read<unknown>(storeName, primaryKey);
164.     const deletedKey = await this.engine.delete(storeName, primaryKey);
165. 
166.     this.notifyListeners(storeName, DEXIE_CRUD_EVENT.DELETING, oldRecord, undefined);
167. 
168.     return deletedKey;
169.   }
170. 
171.   async deleteDatabase(): Promise<boolean> {
172.     try {
173.       await this.engine.purge();
174.       this.logger.info(`Deleting database '${this.dbName}' successful`);
175.       this.dbName = undefined;
176.       return true;
177.     } catch (error) {
178.       this.logger.error(`Deleting database '${this.dbName}' failed`);
179.       throw error;
180.     }
181.   }
182. 
183.   async deleteStore(storeName: string): Promise<void> {
184.     this.logger.info(`Deleting object store '${storeName}' in database '${this.dbName}'`);
185.     await this.engine.deleteAll(storeName);
186.   }
187. 
188.   /**
189.    * Delete multiple database stores.
190.    *
191.    * @param storeNames Names of database stores to delete
192.    * @returns Resolves when the stores have been deleted
193.    */
194.   async deleteStores(storeNames: string[]): Promise<void> {
195.     const deleteStorePromises = storeNames.map(storeName => this.deleteStore(storeName));
196.     await Promise.all(deleteStorePromises);
197.   }
198. 
199.   async deleteEventInConversation(storeName: string, conversationId: string, eventId: string): Promise<number> {
200.     if (this.isTemporaryAndNonPersistent) {
201.       let deletedRecords = 0;
202.       const primaryKeys = await this.readAllPrimaryKeys(storeName);
203. 
204.       for (const primaryKey of primaryKeys) {
205.         const record = await this.load<{conversation: string; id: string; time: number}>(storeName, primaryKey);
206.         if (record?.id === eventId && record.conversation === conversationId) {
207.           await this.delete(storeName, primaryKey);
208.           deletedRecords++;
209.         }
210.       }
211. 
212.       return deletedRecords;
213.     }
214. 
215.     if (!this.db) {
216.       return 0;
217.     }
218. 
219.     return this.db
220.       .table(storeName)
221.       .where('id')
222.       .equals(eventId)
223.       .and(record => record.conversation === conversationId)
224.       .delete();
225.   }
226. 
227.   async deleteEventsByDate(storeName: string, conversationId: string, isoDate?: string): Promise<number> {
228.     if (this.isTemporaryAndNonPersistent) {
229.       let deletedRecords = 0;
230.       const primaryKeys = await this.readAllPrimaryKeys(storeName);
231. 
232.       for (const primaryKey of primaryKeys) {
233.         const record = await this.load<{conversation: string; time: string}>(storeName, primaryKey);
234.         if (record?.conversation === conversationId && (!isoDate || isoDate >= record.time)) {
235.           await this.delete(storeName, primaryKey);
236.           deletedRecords++;
237.         }
238.       }
239. 
240.       return deletedRecords;
241.     }
242. 
243.     if (!this.db) {
244.       return 0;
245.     }
246. 
247.     return this.db
248.       .table(storeName)
249.       .where('conversation')
250.       .equals(conversationId)
251.       .filter(record => !isoDate || isoDate >= record.time)
252.       .delete();
253.   }
254. 
255.   /**
256.    * Returns an array of all records for a given object store.
257.    *
258.    * @param storeName Name of object store
259.    * @returns Resolves with the records from the object store
260.    */
261.   async getAll<T = Object>(storeName: string): Promise<T[]> {
262.     try {
263.       const records = await this.engine.readAll<T>(storeName);
264.       return records.filter(Boolean);
265.     } catch (error) {
266.       this.logger.error(`Failed to load objects from store '${storeName}'`, error);
267.       throw error;
268.     }
269.   }
270. 
271.   /**
272.    * @param tableNames Names of tables to get
273.    * @returns Resolves with matching tables
274.    */
275.   getTables(tableNames: string[]): Dexie.Table<any, any>[] {
276.     if (!this.db) {
277.       return [];
278.     }
